import fs from "node:fs";
import Database from "better-sqlite3";

export const DB_PATH = "/home/user/qwik-app/metadata.db";
export const UPLOADS_DIR = "/home/user/qwik-app/public/uploads";

// Make sure the uploads directory exists on module load.
fs.mkdirSync(UPLOADS_DIR, { recursive: true });

export interface FileRecord {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

let db: Database.Database | undefined;

/**
 * Returns a singleton connection to the SQLite metadata database,
 * creating the `files` table if it does not already exist.
 */
export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    db.exec(`
      CREATE TABLE IF NOT EXISTS files (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        size INTEGER NOT NULL,
        mime TEXT NOT NULL,
        tag TEXT NOT NULL
      )
    `);
  }
  return db;
}

export function listFiles(): FileRecord[] {
  return getDb()
    .prepare("SELECT id, name, size, mime, tag FROM files ORDER BY id ASC")
    .all() as FileRecord[];
}

export function getFileById(id: number): FileRecord | undefined {
  return getDb()
    .prepare("SELECT id, name, size, mime, tag FROM files WHERE id = ?")
    .get(id) as FileRecord | undefined;
}

export function insertFile(
  name: string,
  size: number,
  mime: string,
  tag: string,
): FileRecord {
  const info = getDb()
    .prepare("INSERT INTO files (name, size, mime, tag) VALUES (?, ?, ?, ?)")
    .run(name, size, mime, tag);
  return { id: Number(info.lastInsertRowid), name, size, mime, tag };
}

export function deleteFileRecord(id: number): boolean {
  const info = getDb().prepare("DELETE FROM files WHERE id = ?").run(id);
  return info.changes > 0;
}

/**
 * Disk file names are prefixed with the database id to guarantee
 * uniqueness even if two uploads share the same original file name.
 */
export function diskFileName(id: number, name: string): string {
  return `${id}_${name}`;
}

import fs from "node:fs";
import path from "node:path";
import type { RequestHandler } from "@builder.io/qwik-city";
import { UPLOADS_DIR, diskFileName, insertFile } from "~/lib/db";

export const onPost: RequestHandler = async (requestEvent) => {
  let data: unknown;
  try {
    data = await requestEvent.parseBody();
  } catch {
    requestEvent.json(400, { error: "Invalid form data" });
    return;
  }

  const body = data as Record<string, unknown> | undefined;
  const file = body?.file;
  const tag = body?.tag;

  const isFile =
    !!file &&
    typeof file === "object" &&
    typeof (file as File).arrayBuffer === "function" &&
    typeof (file as File).name === "string";

  if (!isFile) {
    requestEvent.json(400, { error: "Missing or invalid 'file' field" });
    return;
  }

  if (typeof tag !== "string" || tag.trim() === "") {
    requestEvent.json(400, { error: "Missing or invalid 'tag' field" });
    return;
  }

  const uploadedFile = file as File;
  const originalName = path.basename(uploadedFile.name || "upload");

  if (!originalName) {
    requestEvent.json(400, { error: "Missing or invalid file name" });
    return;
  }

  const size = uploadedFile.size;
  const mime = uploadedFile.type || "application/octet-stream";

  const record = insertFile(originalName, size, mime, tag);

  try {
    const arrayBuffer = await uploadedFile.arrayBuffer();
    const destination = path.join(
      UPLOADS_DIR,
      diskFileName(record.id, record.name),
    );
    fs.writeFileSync(destination, Buffer.from(arrayBuffer));
  } catch {
    requestEvent.json(400, { error: "Failed to save uploaded file" });
    return;
  }

  requestEvent.json(201, record);
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { listFiles } from "~/lib/db";

export const onGet: RequestHandler = async (requestEvent) => {
  const files = listFiles();
  requestEvent.json(200, files);
};

import fs from "node:fs";
import path from "node:path";
import type { RequestHandler } from "@builder.io/qwik-city";
import { UPLOADS_DIR, deleteFileRecord, diskFileName, getFileById } from "~/lib/db";

export const onDelete: RequestHandler = async (requestEvent) => {
  const idParam = requestEvent.params.id;
  const id = Number(idParam);

  if (!Number.isInteger(id)) {
    requestEvent.json(400, { error: "Invalid file id" });
    return;
  }

  const record = getFileById(id);

  if (!record) {
    requestEvent.json(404, { error: `File with id ${id} not found` });
    return;
  }

  const filePath = path.join(UPLOADS_DIR, diskFileName(record.id, record.name));

  try {
    fs.unlinkSync(filePath);
  } catch {
    // If the file is already missing from disk, we still proceed to
    // remove the metadata record and report success below.
  }

  deleteFileRecord(id);

  requestEvent.json(200, { success: true });
};

import { $, component$, useSignal, useVisibleTask$ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";

interface FileMeta {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

export default component$(() => {
  const files = useSignal<FileMeta[]>([]);
  const error = useSignal<string>("");
  const loading = useSignal<boolean>(false);

  const refresh = $(async () => {
    const res = await fetch("/files/list");
    if (res.ok) {
      files.value = (await res.json()) as FileMeta[];
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    refresh();
  });

  const handleSubmit = $(async (event: Event) => {
    event.preventDefault();
    error.value = "";

    const form = event.target as HTMLFormElement;
    const formData = new FormData(form);

    if (!(formData.get("file") instanceof File) || !(formData.get("file") as File).name) {
      error.value = "Please choose a file to upload.";
      return;
    }

    loading.value = true;
    try {
      const res = await fetch("/files/upload", {
        method: "POST",
        body: formData,
      });

      if (!res.ok) {
        const body = await res.json().catch(() => ({ error: "Upload failed" }));
        error.value = body.error || "Upload failed";
        return;
      }

      form.reset();
      await refresh();
    } finally {
      loading.value = false;
    }
  });

  const handleDelete = $(async (id: number) => {
    error.value = "";
    const res = await fetch(`/files/${id}`, { method: "DELETE" });
    if (!res.ok) {
      const body = await res.json().catch(() => ({ error: "Delete failed" }));
      error.value = body.error || "Delete failed";
      return;
    }
    await refresh();
  });

  return (
    <>
      <h1>File Explorer</h1>

      <form id="upload-form" preventdefault:submit onSubmit$={handleSubmit}>
        <div>
          <label for="file-input">File</label>
          <input id="file-input" name="file" type="file" required />
        </div>
        <div>
          <label for="tag-input">Tag</label>
          <input
            id="tag-input"
            name="tag"
            type="text"
            placeholder="e.g. documents, images"
            required
          />
        </div>
        <button type="submit" disabled={loading.value}>
          {loading.value ? "Uploading..." : "Upload"}
        </button>
      </form>

      {error.value && <p style={{ color: "red" }}>{error.value}</p>}

      <div id="file-list">
        {files.value.length === 0 && <p>No files uploaded yet.</p>}
        {files.value.map((file) => (
          <div key={file.id} class="file-item" data-id={file.id}>
            <span class="file-name">{file.name}</span>{" "}
            <span class="file-size">{file.size} bytes</span>{" "}
            <span class="file-mime">{file.mime}</span>{" "}
            <span class="file-tag">{file.tag}</span>{" "}
            <button
              type="button"
              class="delete-btn"
              data-id={file.id}
              onClick$={() => handleDelete(file.id)}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </>
  );
});

export const head: DocumentHead = {
  title: "File Explorer",
  meta: [
    {
      name: "description",
      content: "Server-side file explorer with metadata stored in SQLite",
    },
  ],
};

